const TRANSCRIPTS = {"1": [{"start": 0.0, "end": 7.5, "reading": "おはようございます。本日(ほんじつ)は2019年(ねん)の1月(がつ)30日(にち)、これが今年最後(ことしさいご)の旅行(りょこう)になります。ここは東京(とうきょう)浜松町(はままつちょう)です。", "zh": "早上好。今天是2019年1月30日，这将是今年最后一次旅行。这里是东京滨松町。"}, {"start": 7.5, "end": 15.5, "reading": "朝一番(あさいちばん)の羽田空港(はねだくうこう)初(はつ)、福岡空港(ふくおかくうこう)勇気(ゆうき)の前日(ぜんじつ)空(そら)の飛行機(ひこうき)に乗って(のって)、これから福岡(ふくおか)に仕事(しごと)がありますので向か(むか)うことになっています。", "zh": "乘坐清晨第一班从羽田机场出发、飞往福冈机场的全日空的飞机，接下来因为福冈有工作，所以要前往福冈。"}, {"start": 15.5, "end": 26.5, "reading": "ただ、福岡(ふくおか)には本当(ほんとう)は午後(ごご)ぐらいにつけばいいんですけど、仕事(しごと)のために福岡(ふくおか)まで行って(いって)たらそれで帰っ(かえっ)てくるだけというのでは何か(なにか)味けない(あじけない)から、じゃあ朝一番(あさいちばん)の飛行機(ひこうき)にとは早め(はやめ)ておいたのでした。", "zh": "只是，福冈其实下午左右到就可以了，但是如果为了工作去福冈，然后只是回来的话总觉得乏味，所以就提早订了清晨第一班的飞机。"}, {"start": 27.0, "end": 37.5, "reading": "確か(たしか)羽田(はねだ)6時(とき)15分と(ふんと)か20分と(ふんと)かそれぐらいに出る(でる)瓶(かめ)だったと思い(おもい)ます。もう眠く(ねむく)てですね、前日(ぜんじつ)も2時(とき)30ぐらいまで起き(おき)てましたんで、体(からだ)も臭く(くさく)て前(まえ)も後ろ(うしろ)も分か(わか)らんという状態(じょうたい)なんですが、", "zh": "我记得好像是羽田6点15分或者20分左右出发的航班。已经很困了，前一天也一直醒到2点30分左右，所以身体也很累，前后都分不清的状态，"}, {"start": 37.5, "end": 46.5, "reading": "ちょうど窓側(まどがわ)ですから持た(もた)れてですね、ここでゆっくり福岡空港(ふくおかくうこう)につくまでは休み(やすみ)を取る(とる)ことができました。もう完全(かんぜん)に熟睡(じゅくすい)でしたからね、タイヤフも回復(かいふく)しております。", "zh": "正好是靠窗的位置，所以靠着，在这里直到抵达福冈机场都能悠闲地休息。因为完全熟睡了，疲劳也恢复了。"}, {"start": 48.5, "end": 54.5, "reading": "全日空(ぜんにっくう)の方(ほう)から、よいお年(ねん)を迎え(むかえ)ください。挨拶(あいさつ)がありました。私(わたし)の仕事(しごと)はもう少し(すこし)だけ続き(つづき)ます。", "zh": "全日空那边说了，请迎接一个美好的新年，打了招呼。我的工作还要再持续一点点。"}, {"start": 54.5, "end": 60.5, "reading": "さて福岡空港(ふくおかくうこう)のご紹介(しょうかい)をします。バーンと出て(でて)いるのは地元(じもと)の大き(おおき)な講座(こうざ)会社(かいしゃ)アソーグループの広告(こうこく)です。", "zh": "那么来介绍一下福冈机场。醒目地展示出来的是当地大型讲座公司麻生集团的广告。"}, {"start": 60.5, "end": 69.5, "reading": "そして、ゼニックの手荷物(てにもつ)預け(あずけ)状の(じょうの)ところは行って(いって)ですね、もう先に(さきに)帰り(かえり)の飛行機(ひこうき)に荷物(にもつ)を預け(あずけ)てしまうことにしました。本日(ほんじつ)は被害(ひがい)旅行(りょこう)になっています。", "zh": "然后，去了全日空的行李托运处，决定先把行李托运到返程的飞机上。今天是当天往返的旅行。"}, {"start": 69.5, "end": 79.5, "reading": "福岡(ふくおか)の街並(まちなみ)みをあちこち歩く(あるく)のに大きい(おおきい)荷物(にもつ)を持っ(もっ)て歩く(あるく)のは面倒(めんどう)だし、そしてまたコインロッカー台(だい)を節約(せつやく)したいんで、じゃあ先に(さきに)飛行機(ひこうき)に荷物(にもつ)を預け(あずけ)ちゃえばいいじゃないか、それできるんだそうですね。", "zh": "在福冈的街道上到处走的时候拿着大行李走很麻烦，而且又想节省投币式寄物柜的费用，所以想着先把行李寄到飞机上不就好了吗，据说这是可以做到的。"}, {"start": 79.5, "end": 89.5, "reading": "で、空港(くうこう)の中(なか)、どんなのがあるのか、朝(あさ)は空い(あい)てますんで、下見(したみ)くらいをするにはいい時間(じかん)です。ラーメン、福岡空港(ふくおかくうこう)、カスオーロみたいに書い(かい)てありましたけど、いろんなラーメン屋(や)があります。", "zh": "然后，机场里面有什么呢，早上人少，所以是适合看一看的时间。写着拉面、福冈机场、之类的，有各种各样的拉面店。"}, {"start": 89.5, "end": 97.5, "reading": "でもね、さっきのメニューとかも見て(みて)いただければわかるんですが、福岡(ふくおか)墓(はか)多(た)のラーメンだけが、ここに中に(なかに)あるわけではなくて、いろんな地方(ちほう)のがありましたね。", "zh": "但是，看一下刚才的菜单等就会明白，这里面并不只有福冈博多的拉面，还有各种各样地方的。"}, {"start": 97.5, "end": 106.5, "reading": "それからこちらは、これね、寿司屋(すしや)かな?おとば寿司(すし)って書い(かい)てあります。これ大変有名(たいへんゆうめい)な福岡(ふくおか)墓(はか)多(た)の寿司屋(すしや)さんだそうです。", "zh": "然后这边，这个，是寿司店吗？写着乙羽寿司。据说这是非常有名的福冈博多的寿司店。"}, {"start": 106.5, "end": 113.5, "reading": "本日(ほんじつ)のおすすめは、ゴマサバとなっています。福岡県(ふくおかけん)は全国(ぜんこく)で多分(たぶん)ここだけ、生の(うの)ままでサバが食べ(たべ)られてしまうという変わ(かわ)った場所(ばしょ)です。", "zh": "今天的推荐是芝麻鲭鱼。福冈县在全国大概只有这里，是可以生着吃鲭鱼的与众不同的地方。"}, {"start": 113.5, "end": 118.5, "reading": "心(こころ)サバを食べて(たべて)も生(なま)で問題(もんだい)ないらしいですね。近く(ちかく)には、イカの名称(めいしょう)、よぶ子(こ)もあります。", "zh": "据说吃新鲜鲭鱼生吃也没有问题。附近还有乌贼的名产，呼子。"}, {"start": 118.5, "end": 126.5, "reading": "それからこちらは、持つ(もつ)鍋屋(なべや)さん。当然(とうぜん)まだ朝(あさ)の早い(はやい)時間(じかん)ですからね、まだ8時代(じだい)なんで閉ま(しま)ってるわけですけど、たくさんなんかお土産(みやげ)を売っ(うっ)てますね。", "zh": "然后这边是牛杂锅店。当然现在还是早晨的早时间，才8点多，所以关着门，不过在卖很多土特产呢。"}, {"start": 126.5, "end": 134.5, "reading": "隠れ(かくれ)た名店(めいてん)は、この幼稚園(ようちえん)屋(や)と書い(かい)てありますけど、ロイヤルという、現在(げんざい)のファミリーレストランの元祖(がんそ)となるようなお店(みせ)だそうです。", "zh": "隐藏的名店，写着这家幼稚园屋，是叫做皇家的，据说是成为现在家庭餐厅鼻祖的店。"}, {"start": 134.5, "end": 142.5, "reading": "何で(なんで)も私(わたし)が聞い(きい)た限り(かぎり)では、この福岡市(ふくおかし)で営業(えいぎょう)を始め(はじめ)た、ロイヤルというお店(みせ)が全国(ぜんこく)のファミリーレストランの先駆け(さきがけ)となったのだそうで、", "zh": "无论如何据我所听说的，在这个福冈市开始营业的名叫皇家的店，成为了全国家庭餐厅的先驱。"}, {"start": 142.5, "end": 147.5, "reading": "もともとは、新宿(しんじゅく)に相手(あいて)にして養殖(ようしょく)の提供(ていきょう)を始め(はじめ)た、そういうところだったそうですね。", "zh": "本来，是以新宿为对象开始提供养殖的，据说是那样的地方。"}, {"start": 147.5, "end": 153.5, "reading": "私(わたし)も気づ(きづ)かずに二度(にど)三度(さんど)、そんな名店(めいてん)だったとはね、知り(しり)ませんでしたが、食べた(たべた)ことがあります。", "zh": "我也没有注意到，有过两三次，没想到是那样的名店，虽然不知道，但吃过。"}, {"start": 153.5, "end": 159.5, "reading": "この中(なか)は本当(ほんとう)に福岡(ふくおか)は代表(だいひょう)する名店(めいてん)が揃っ(そろっ)ていて、福岡空港(ふくおかくうこう)に来て(きて)何か(なにか)食べて(たべて)帰る(かえる)だけでもいいかもしれないですね。", "zh": "这里面真的聚集了代表福冈的名店，也许只是来福冈机场吃点什么再回去也不错。"}, {"start": 159.5, "end": 166.5, "reading": "さて、そしてそこからまたすぐに地下(ちか)で直結(ちょっけつ)している福岡空港(ふくおかくうこう)初(はつ)の地下鉄(ちかてつ)空港線(くうこうせん)に乗り(のり)ます。", "zh": "那么，然后从那里又马上乘坐在地下直接连通的、从福冈机场出发的地铁机场线。"}, {"start": 166.5, "end": 172.5, "reading": "空港線(くうこうせん)はJRとリンクした鉄道(てつどう)システム。この列車(れっしゃ)もJR線(せん)から直通(ちょくつう)をしてきました。", "zh": "机场线是与JR联通的铁路系统。这趟列车也是从JR线直通过来的。"}, {"start": 172.5, "end": 176.5, "reading": "上の(うえの)釣り(つり)川(かわ)を掴む(つかむ)ところとか座席(ざせき)の作り(つくり)とか、随分(ずいぶん)変わ(かわ)っています。", "zh": "上面抓吊环的地方和座位的构造，都相当不同。"}, {"start": 176.5, "end": 182.5, "reading": "JR蓄積(ちくせき)線(せん)で、水戸岡(みとおか)エイジさんという先(さき)族(ぞく)のデザイナーの人(にん)が手掛け(てがけ)た作り(つくり)をしていて、", "zh": "是JR九州线上，由名叫水户冈锐治的先驱设计师所做的构造，"}, {"start": 182.5, "end": 186.5, "reading": "それが空港線(くうこうせん)の中(なか)でも見ら(みら)れるんですね。これもまた吸収(きゅうしゅう)らしさが現れ(あらわれ)ています。", "zh": "这个在机场线里面也能看到。这也体现出了九州的风格。"}, {"start": 186.5, "end": 192.5, "reading": "福岡空港(ふくおかくうこう)からはかたまで5分(ふん)、泣か(なか)すまで9分(ふん)、天神(てんじん)は11分(ふん)、恐る(おそる)べき近さ(ちかさ)です。", "zh": "从福冈机场到博多5分钟，到中洲川端9分钟，天神11分钟，近得可怕。"}, {"start": 192.5, "end": 195.5, "reading": "これはね、福岡空港(ふくおかくうこう)は本当(ほんとう)に何度(なんど)も言う(いう)ようですけど、", "zh": "这个啊，福冈机场真的，虽然说了很多次，"}, {"start": 195.5, "end": 202.5, "reading": "長(ちょう)空港(くうこう)と福岡空港(ふくおかくうこう)が私(わたし)が知って(しって)いる中(なか)で、便利(べんり)な空港(くうこう)のリッチノイ空港(くうこう)のツートップを乗って(のって)いて、", "zh": "长机场和福冈机场，在我所知道的范围内，是便利的机场中的两大巨头，"}, {"start": 202.5, "end": 205.5, "reading": "飛行機(ひこうき)最高(さいこう)って、本当(ほんとう)に心(こころ)から思い(おもい)ますね。", "zh": "飞机最棒，真的从心底里这么觉得。"}, {"start": 205.5, "end": 211.5, "reading": "さて、やってきましたのは福岡空港(ふくおかくうこう)から大体(だいたい)15分(ふん)ぐらいのところ、アカサカというところです。", "zh": "那么，来到的是距离福冈机场大约15分钟左右的地方，赤坂这个地方。"}, {"start": 211.5, "end": 215.5, "reading": "お城(しろ)が近い(ちかい)んですね。東京(とうきょう)にもお城(しろ)の近く(ちかく)にアカサカ見つ(みつ)けというところありますね。", "zh": "离城堡很近呢。东京也有城堡附近的赤坂见附这个地方呢。"}, {"start": 215.5, "end": 218.5, "reading": "大体(だいたい)こんな風(かぜ)に移動(いどう)してきたと地図(ちず)でご紹介(しょうかい)します。", "zh": "大体上是这样移动过来的，用地图来介绍。"}, {"start": 219.5, "end": 225.5, "reading": "福岡空港(ふくおかくうこう)の地下(ちか)から地下鉄(ちかてつ)に乗って(のって)中心地(ちゅうしんち)、墓(はか)を通り(とうり)抜け(ぬけ)、さらにそこから海(うみ)の方(ほう)へ出て(でて)きました。", "zh": "从福冈机场的地下乘坐地铁，穿过中心地带博多，再从那里向着海的方向出来了。"}, {"start": 225.5, "end": 228.5, "reading": "これからですね、長浜(ながはま)港(みなと)というところに行き(いき)ます。", "zh": "接下来要去长浜港这个地方。"}, {"start": 228.5, "end": 231.5, "reading": "長浜(ながはま)ラーメンが有名(ゆうめい)ですが、皆さん(みなさん)ご存知(ぞんじ)でしょうか?", "zh": "长浜拉面很有名，大家知道吗？"}, {"start": 231.5, "end": 239.5, "reading": "そこはもともとうお市場(しじょう)などがありまして、福岡県(ふくおかけん)にやってくる、福岡市(ふくおかし)にやってくるお魚(さかな)の玄関口(げんかんぐち)でもあります。", "zh": "那里原本有鱼市场等，也是来到福冈县、来到福冈市的鱼的玄关口。"}, {"start": 239.5, "end": 243.5, "reading": "ちょっと向こう(むこう)に中(なか)、おろし売り場(うりば)と書い(かい)てありますがね。", "zh": "稍微那边中间，写着批发市场呢。"}], "2": [{"start": 0.0, "end": 4.0, "reading": "先行(せんこう)一話(いちわ)、お魚(さかな)なんですよ。まずこれから食べ(たべ)るのはお魚(さかな)です。", "zh": "首先第一件事，是鱼呢。接下来先要吃的是鱼。"}, {"start": 4.0, "end": 9.0, "reading": "この福岡(ふくおか)はかたはさっきの空港(くうこう)でもそうでしたが、美味しい(おいしい)ものがたくさん揃っ(そろっ)ているところ。", "zh": "这个福冈博多，就像刚才的机场也是那样，是聚集了很多美味食物的地方。"}, {"start": 9.0, "end": 14.0, "reading": "特に(とくに)お魚(さかな)、これがラーメンが有名(ゆうめい)ですけれども、非常に(ひじょうに)美味しい(おいしい)そうです。", "zh": "特别是鱼，虽然这个是拉面有名，但据说非常好吃。"}, {"start": 14.0, "end": 21.0, "reading": "このラーメンがどちらかと、美味しい(おいしい)お魚(さかな)がラーメンを生ん(うん)だと、そういうふうに考え(かんがえ)てもいいかもしれません。", "zh": "这个拉面算是哪一边呢，说是美味的鱼生出了拉面，这样想也许也可以。"}, {"start": 21.0, "end": 27.0, "reading": "さっそくその一番(いちばん)のすぐ脇(わき)にある、先行(せんこう)一番(いちばん)市場(しじょう)海岸(かいがん)、一番(いちばん)海岸(かいがん)かな、その中に(なかに)入り(いり)ます。", "zh": "马上进入就在那个一番旁边的，先行一番市场海岸，是一番海岸吧，走到它里面。"}, {"start": 27.0, "end": 31.0, "reading": "もうすでにあらかじめ、お正月(しょうがつ)の準備(じゅんび)の飾り(かざり)付け(つけ)がしてあります。", "zh": "已经事先做好了迎接新年的装饰布置。"}, {"start": 31.0, "end": 37.0, "reading": "この一番(いちばん)海岸(かいがん)の中に(なかに)入る(いる)と、入っ(いっっ)てすぐの左側(ひだりがわ)ですが、海天(かいてん)寿(ひさし)、うおたつというところがあって、", "zh": "一进到这个一番海岸里面，进去马上的左边，有一个叫海天寿，鱼辰的地方，"}, {"start": 37.0, "end": 43.0, "reading": "まあ、これは今回(こんかい)私(わたし)が福岡(ふくおか)に仕事(しごと)で行った(いった)んですけど、そこで寿司(すし)だったらここで絶対(ぜったい)に食べ(たべ)なさいというふうに教え(おしえ)ていただき、", "zh": "嗯，这次是我因为工作去了福冈，在那里有人告诉我说，要吃寿司的话一定要在这里吃，"}, {"start": 43.0, "end": 45.0, "reading": "よし、じゃあここへ行って(いって)食べ(たべ)よう。", "zh": "好，那么就去这里吃吧。"}, {"start": 45.0, "end": 49.0, "reading": "こんなものね、いろいろと注文(ちゅうもん)しました。どんどん注文(ちゅうもん)したんですが、", "zh": "这样的东西呢，点了各种各样的。一个接一个地点了，"}, {"start": 49.0, "end": 52.0, "reading": "残念(ざんねん)ながらあいにくサバがこの日入(ひのいり)っていなかったので、", "zh": "可惜不巧这天没有进鲭鱼，"}, {"start": 52.0, "end": 57.0, "reading": "全国(ぜんこく)で多分(たぶん)ここだけ生(なま)でサバを食べ(たべ)られる、ごまサバはなかったんですが、", "zh": "全国大概只有这里能生吃鲭鱼，芝麻鲭鱼是没有，"}, {"start": 57.0, "end": 64.0, "reading": "えっとね、ごま味(あじ)とかね、なんかそういう他の(ほかの)ごまの、あのこうあえたようなやつあって、味(あじ)はとても美味しか(おいしか)ったですよ。", "zh": "嗯，有芝麻味之类的，呢，有其他那种用芝麻拌过的东西，味道非常好吃哦。"}, {"start": 64.0, "end": 68.0, "reading": "魚(さかな)の味を(あじを)左右(さゆう)するのはもちろんどんな高級(こうきゅう)な魚(さかな)かとかそういうのもあると思う(おもう)んですが、", "zh": "左右鱼的味道的，当然也有是多么高级的鱼之类的因素，我想，"}, {"start": 68.0, "end": 73.0, "reading": "やっぱり新鮮(しんせん)なんじゃないですか。で、ここのやつはね、食べて(たべて)て本当(ほんとう)に新鮮(しんせん)に感じ(かんじ)ましたよ。", "zh": "还是新鲜吧。然后，这里的东西呢，吃的时候真的感觉很新鲜哦。"}, {"start": 73.0, "end": 79.0, "reading": "よし、よくわかんないですけど、寿司(すし)とかね、正直(しょうじき)どんなところで食べて(たべて)も、なんか味(あじ)変わ(かわ)んないんじゃないかなとか思う(おもう)んですけど、", "zh": "好，我不太明白，不过寿司之类的，说实话不管在什么地方吃，是不是味道都没什么变化，我会这么想，"}, {"start": 79.0, "end": 84.0, "reading": "実際に(じっさいに)は変わり(かわり)ますよね。食べ(たべ)るお店(みせ)によって、なんであんなに寿司(すし)の味(あじ)が似た(にた)ような料理(りょうり)なのに、", "zh": "实际上是会变的吧。因为吃的店不同，为什么明明是相似的料理，寿司的味道会那么不同，"}, {"start": 84.0, "end": 90.0, "reading": "調理方法(ちょうりほうほう)とか味付け(あじつけ)の差(さ)はないのに不思議(ふしぎ)なことですが、この店(みせ)はもう確かに(たしかに)ね、超(ちょう)うまかったですよ。", "zh": "明明烹调方法和调味没有差别，很不可思议，不过这家店确实呢，超级好吃哦。"}, {"start": 90.0, "end": 94.0, "reading": "あの、これなんか動画(どうが)のネタで言って(いって)るわけじゃなくて本当(ほんとう)に正直(しょうじき)に心(こころ)から言い(いい)ますけど、", "zh": "那个，这个并不是为了视频的话题才说的，是真的老实地发自内心地说，"}, {"start": 94.0, "end": 99.0, "reading": "ここで寿司(すし)食べて(たべて)帰る(かえる)ためだけに福岡(ふくおか)に来て(きて)もいいと思い(おもい)ます。", "zh": "我觉得只为了在这里吃寿司再回去而来福冈也可以。"}, {"start": 99.0, "end": 102.0, "reading": "まあ実際に(じっさいに)はそれだけじゃもったいないけど、これをメインの目的地(もくてきち)として、", "zh": "嗯，实际上只是那样的话太可惜了，不过把这个作为主要的目的地，"}, {"start": 102.0, "end": 105.0, "reading": "福岡(ふくおか)旅行(りょこう)を考え(かんがえ)てもいいと思い(おもい)ますよ。そういうお店(みせ)です。", "zh": "考虑福冈旅行也可以哦。就是这样的店。"}, {"start": 106.0, "end": 109.0, "reading": "どんどん付き(つき)付き(つき)頼ま(たのま)れて出て(でて)くるんですけど、", "zh": "接连不断地被点单然后端出来，"}, {"start": 109.0, "end": 112.0, "reading": "これはお醤油(しょうゆ)がですね、結構(けっこう)甘い(あまい)やつです。九州(きゅうしゅう)のお醤油(しょうゆ)。", "zh": "这个酱油呢，是相当甜的那种。九州的酱油。"}, {"start": 112.0, "end": 115.0, "reading": "まあこれまだ九州(きゅうしゅう)の北(きた)のほうなので、福岡県(ふくおかけん)はあの、", "zh": "嗯，这里还是九州的北边，所以福冈县那个，"}, {"start": 115.0, "end": 119.0, "reading": "鹿児(かこ)島(しま)とか宮崎(みやざき)ほど醤油(しょうゆ)は甘く(あまく)ないのかなというような気が(きが)なんかするんですが、", "zh": "我总觉得好像酱油没有鹿儿岛或宫崎那么甜，"}, {"start": 119.0, "end": 123.0, "reading": "これはあの、お魚(さかな)につけたりとかですね、今(いま)見せ(みせ)ましたかね。", "zh": "这个呢，蘸在鱼上之类的，刚才给大家看了吧。"}, {"start": 123.0, "end": 128.0, "reading": "障害(しょうがい)にこう浸し(ひたし)て食べた(たべた)りとかするのがまたこう、ちょっと爽や(さわや)かでね、美味しか(おいしか)ったですね。", "zh": "蘸在酱油里吃之类的，又有点清爽，很好吃呢。"}, {"start": 128.0, "end": 132.0, "reading": "これは、チュートロラかオートロラかを食べ(たべ)ようと、たまにですね、", "zh": "这个是，想吃中腹肉或大腹肉，偶尔呢，"}, {"start": 132.0, "end": 136.0, "reading": "滅多(めった)に食べ(たべ)ないんですが、食べて(たべて)みましたが、これもふわっと美味しか(おいしか)ったですね。", "zh": "很少吃，不过吃了，这个也是软软的很好吃呢。"}, {"start": 136.0, "end": 143.6, "reading": "見て(みて)るとローストビーフみたいだよな。何か(なにか)にたとえたくなってしまいます。", "zh": "看着像烤牛肉一样吧。忍不住想拿什么来比喻。"}, {"start": 143.6, "end": 147.6, "reading": "ズラッと並び(ならび)ます。ハラミ4巻(かん)森(もり)みたいなのも聞き(きき)ました。", "zh": "哗地一排排摆开。也听说了牛横隔膜四贯之类的东西。"}, {"start": 147.6, "end": 151.6, "reading": "もう何だ(なんだ)ったのかね、ごめんなさい。わったく何も(なにも)覚え(おぼえ)てないんですけど、美味しけ(おいしけ)ればいいですよね。", "zh": "到底是什么来着，对不起。完全什么都不记得了，不过好吃就行了吧。"}, {"start": 151.6, "end": 155.6, "reading": "この時(とき)何を(なにを)食べた(たべた)かわざわざメモもしたんですが、そのメモをどっかにいってしまいました。", "zh": "这时候吃了什么，我还特意做了笔记，不过那个笔记不知丢到哪里去了。"}, {"start": 155.6, "end": 159.6, "reading": "しかし、美味しか(おいしか)ったということは覚え(おぼえ)ているし、味(あじ)もまた覚え(おぼえ)ています。", "zh": "但是，我记得很好吃，味道也还记得。"}, {"start": 159.6, "end": 162.6, "reading": "味を(あじを)覚え(おぼえ)てるってのはね、本当(ほんとう)に美味しか(おいしか)ったんだろうなと思う(おもう)んですけど、", "zh": "记得味道呢，我想真的是很好吃吧，"}, {"start": 162.6, "end": 165.6, "reading": "どうですか?これ、珍しく(めずらしく)美味し(おいし)そうな顔(かお)してるでしょ。", "zh": "怎么样？这个，难得露出好吃的表情吧。"}, {"start": 165.6, "end": 169.6, "reading": "それから他に(ほかに)もこの一番(いちばん)開館(かいかん)の中に(なかに)は、いろいろ定食屋(ていしょくや)さんなどがありまして、", "zh": "然后除此之外这个一番海岸里面，还有各种定食店之类的，"}, {"start": 169.6, "end": 172.6, "reading": "あらざき定食(ていしょく)を850円(えん)、めちゃくちゃ美味し(おいし)そうですよね。", "zh": "荒崎定食850日元，看起来超级好吃吧。"}, {"start": 172.6, "end": 176.6, "reading": "あれね、終了(しゅうりょう)。明太子(めんたいこ)がありますよ。いくらだったのかな?気に(きに)なります。", "zh": "那个呢，结束。有明太子哦。是多少钱来着？很在意。"}, {"start": 176.6, "end": 180.6, "reading": "刺身(さしみ)定食(ていしょく)も刺身(さしみ)がどっすり、赤(あか)ウゴにつけて定食(ていしょく)は1050円(えん)。", "zh": "生鱼片定食也是生鱼片满满的，蘸红虾的定食是1050日元。"}, {"start": 180.6, "end": 183.6, "reading": "お昼(ひる)ご飯(めし)としてはちょっと高い(たかい)ブルーかもしれないけど、でも、", "zh": "作为午饭也许有点贵的感觉，不过，但是，"}, {"start": 183.6, "end": 187.6, "reading": "デラックスな大き(おおき)な赤(あか)ウゴが2本(ほん)で載っ(のっ)てましたね。", "zh": "豪华的大红虾放了两只呢。"}, {"start": 187.6, "end": 191.6, "reading": "さて、このような一場(いちじょう)で働く(はたらく)人(にん)向け(むけ)の食べ物(たべもの)が、", "zh": "那么，面向在这样的市场里工作的人的食物，"}, {"start": 192.6, "end": 196.6, "reading": "長浜(ながはま)ラーメンです。現在(げんざい)では、ハカタラーメンと混同(こんどう)されていますが、", "zh": "就是长浜拉面。现在虽然和博多拉面被混为一谈，"}, {"start": 196.6, "end": 202.6, "reading": "細い(こまい)麺(めん)と豚骨(とんこつ)のスープが有名(ゆうめい)な長浜(ながはま)や、これが長浜(ながはま)ラーメンのガンストとされています。", "zh": "以细面和猪骨汤闻名的长浜啊，这被认为是长浜拉面的原点。"}, {"start": 202.6, "end": 205.6, "reading": "現在(げんざい)でもね、小規模(しょうきぼ)ながらあるそうなんですが、", "zh": "听说现在虽然规模很小，但还是有的，"}, {"start": 205.6, "end": 210.6, "reading": "あの、昔(むかし)この一場(いちじょう)から少し(すこし)外れ(はずれ)た、まあ1個(こ)お隣(となり)の通り(とうり)かな、同じ(おなじ)ブロックかな、", "zh": "那个，以前从这个市场稍微偏一点的地方，嗯，大概是隔壁一条街吧，或者是同一个街区吧，"}, {"start": 210.6, "end": 213.6, "reading": "そこのところにですね、このようにズラリと一場(いちじょう)が並ん(ならん)でいまして、", "zh": "在那个地方呢，像这样一个接一个地排着市场，"}, {"start": 213.6, "end": 218.6, "reading": "そこではラーメンのお店(みせ)もあったし、それから他に(ほかに)もさまざまなお店(みせ)とかですね、", "zh": "那里既有拉面店，还有其他各种各样的店之类的，"}, {"start": 218.6, "end": 221.6, "reading": "夜(よる)になっても色んな(いろんな)お店(みせ)が立ち(たち)並ん(ならん)でいったということです。", "zh": "就是说到了晚上也有各种各样的店排列着。"}, {"start": 221.6, "end": 226.6, "reading": "まあ、むしろ夜(よる)になると屋台(やたい)は出て(でて)きたのかな、今(いま)でもこのあたりに行け(いけ)ば屋台(やたい)は出る(でる)そうなんですが、", "zh": "嗯，倒不如说到了晚上摊位会出来吧，听说现在去这一带的话摊位也会出来，"}, {"start": 227.6, "end": 232.6, "reading": "こちらが長浜(ながはま)港(みなと)。長浜(ながはま)港(みなと)とハカタ港(みなと)というのは、", "zh": "这里是长浜港。长浜港和博多港，"}, {"start": 232.6, "end": 235.6, "reading": "厳密(げんみつ)にはというか全く(まったく)違う(ちがう)場所(ばしょ)です。", "zh": "严格来说，或者说是完全不同的地方。"}, {"start": 235.6, "end": 238.6, "reading": "これについてはまた後で(あとで)詳しく(くわしく)紹介(しょうかい)しようと思う(おもう)んですが、", "zh": "关于这一点，我打算之后再详细介绍，"}, {"start": 238.6, "end": 242.6, "reading": "こちらはどちらかというと、ウオイチバーとかね、", "zh": "这里与其说是什么，不如说是鱼市场之类的，"}], "3": [{"start": 0.0, "end": 3.0, "reading": "量(りょう)をするか、まあそういった関係(かんけい)のものがここに並ん(ならん)でいまして、", "zh": "做量的，嗯，那样的相关的东西排列在这里，"}, {"start": 3.0, "end": 7.0, "reading": "さっき映っ(うつっ)ていたピンク色(いろ)の建物(たてもの)も氷(こおり)屋(や)さんだったそうですね。", "zh": "刚才映出来的粉色建筑物据说也是冰店呢。"}, {"start": 8.0, "end": 13.0, "reading": "そしてこの道(みち)、今(いま)では開発(かいはつ)されて、昔(むかし)のおもかげはしっかりなくなりマンションなどが並ん(ならん)でいたようですが、", "zh": "然后这条路，现在被开发了，以前的面貌已经完全没有了，好像排着公寓之类的，"}, {"start": 13.0, "end": 18.0, "reading": "かつてはこの1本(ほん)の長い(ながい)道(みち)に屋台(やたい)がズラズラと並ん(ならん)で、", "zh": "以前在这一条长长的路上摊位一个接一个地排着，"}, {"start": 18.0, "end": 21.0, "reading": "夜(よる)になるとにぎわったんだそうです。", "zh": "据说到了晚上就热闹起来。"}, {"start": 21.0, "end": 28.5, "reading": "福岡(ふくおか)ではね、長浜(ながはま)とそれから天神(てんじん)の方(ほう)にも屋台(やたい)外(そと)があるの有名(ゆうめい)ですよね。", "zh": "在福冈呢，长浜和天神那边也有摊位街，很有名吧。"}, {"start": 28.5, "end": 31.5, "reading": "ここからちょっと一番(いちばん)の方を(ほうを)覗い(のぞい)てみると、", "zh": "从这里稍微往最里面看一下的话，"}, {"start": 31.5, "end": 37.5, "reading": "すごい古そ(ふるそ)うな建物(たてもの)の中に(なかに)、今(いま)でもおそらく一番(いちばん)の一向(いっこう)けの食堂(しょくどう)と生まれ(うまれ)るものが並ん(ならん)でいました。", "zh": "在看起来非常古老的建筑物里，现在大概也排着面向一番的食堂之类的东西。"}, {"start": 39.9, "end": 43.9, "reading": "で、この長浜屋(ながはまや)さんなんですが、福岡(ふくおか)のラーメンは大変有名(たいへんゆうめい)だと思い(おもい)ますけど、", "zh": "然后，这个长浜屋呢，福冈的拉面我想是非常有名的，"}, {"start": 43.9, "end": 46.9, "reading": "まあそこの本当(ほんとう)にここが一番(いちばん)古く(ふるく)岩(いわ)草(くさ)だということで、", "zh": "嗯，那里据说真的是这里最古老的岩草，"}, {"start": 46.9, "end": 49.9, "reading": "もう福岡(ふくおか)のラーメンを見え(みえ)た人(にん)がたくさんいるわけですからね、", "zh": "因为已经有很多看到福冈拉面的人了呢，"}, {"start": 49.9, "end": 52.9, "reading": "観光(かんこう)の拠点(きょてん)として大人気(だいにんき)です。ズラッと並ん(ならん)でいます。", "zh": "作为观光的据点非常受欢迎。排得长长的。"}, {"start": 53.9, "end": 56.9, "reading": "中(なか)でもね、なんか私(わたし)はこの店(みせ)には入っ(いっっ)たことはないんですけど、", "zh": "其中呢，嗯，我没有进过这家店，"}, {"start": 56.9, "end": 58.9, "reading": "席(せき)に着く(つく)と思う(おもう)それと同時に(どうじに)ラーメンが出て(でて)くる、", "zh": "据说一坐下的同时拉面就出来了，"}, {"start": 58.9, "end": 60.9, "reading": "メニューはラーメンただ一つ(ひとつ)だけと、", "zh": "菜单只有拉面一种，"}, {"start": 60.9, "end": 62.9, "reading": "昔(むかし)からなんかそんな話(はなし)が伝わ(つたわ)っているそうでして、", "zh": "从以前起好像就传着这样的话，"}, {"start": 62.9, "end": 66.9, "reading": "ものすごい勢い(いきおい)で次々(つぎつぎ)豚骨(とんこつ)ラーメンが提供(ていきょう)されているんだそうです。", "zh": "据说以非常猛的势头接连不断地提供猪骨拉面。"}, {"start": 66.9, "end": 68.9, "reading": "カエダマという文化(ぶんか)も、なんと言う(いう)、", "zh": "换面这种文化，怎么说呢，"}, {"start": 68.9, "end": 71.9, "reading": "もうここから始ま(はじま)ったらがそんな話(はなし)がありますね。", "zh": "也有这样的说法，说已经是从这里开始的。"}, {"start": 71.9, "end": 74.9, "reading": "なんですが、ここに岩(いわ)草(くさ)長浜屋(ながはまや)があるのかと思った(おもった)ら、", "zh": "不过，我想着这里有岩草长浜屋吗，"}, {"start": 74.9, "end": 77.9, "reading": "向こう(むこう)を見る(みる)とですね、あちらに岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)、", "zh": "往那边看的话呢，那边有岩草拉面长浜屋，"}, {"start": 77.9, "end": 79.9, "reading": "なんと登録(とうろく)消費(しょうひ)をもとったみたいですね。", "zh": "竟然好像也注册了商标呢。"}, {"start": 79.9, "end": 83.9, "reading": "岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)の、", "zh": "岩草拉面长浜屋的，"}, {"start": 83.9, "end": 86.9, "reading": "ご愛子(あいこ)ありがとうございますかな。", "zh": "是不是说承蒙惠顾，谢谢呢。"}, {"start": 86.9, "end": 90.9, "reading": "よく見て(みて)みると、長浜(ながはま)奥(おく)という時(とき)とは長浜(ながはま)居(きょ)へという時(とき)で", "zh": "仔细看的话，有写作长浜屋的和写作长浜居的，"}, {"start": 90.9, "end": 93.9, "reading": "二種類(にしゅるい)あるんですが、実は(じつは)ここにはですね、", "zh": "有两种，其实在这里呢，"}, {"start": 93.9, "end": 96.9, "reading": "岩(いわ)草(くさ)長浜屋(ながはまや)と作る(つくる)ラーメン屋(や)さんが3つあって、", "zh": "有三家叫作岩草长浜屋的拉面店，"}, {"start": 96.9, "end": 99.9, "reading": "しかもどれも大変(たいへん)多く(おおく)関係(かんけい)があるんですね。", "zh": "而且每一个都有很大的关系呢。"}, {"start": 99.9, "end": 103.9, "reading": "まず一番上(いちばんうえ)、岩(いわ)草(くさ)長浜(ながはま)奥(おく)と書い(かい)てあるこの店(みせ)が", "zh": "首先最上面，写着元祖长滨屋的这家店"}, {"start": 103.9, "end": 105.9, "reading": "紹介(しょうかい)した通り(とうり)、一番(いちばん)古く(ふるく)からやっていて、", "zh": "正如所介绍的，是从最早开始营业的，"}, {"start": 105.9, "end": 109.9, "reading": "おそらく岩(いわ)草(くさ)の定義(ていぎ)通り(とうり)当て(あて)はまる、", "zh": "大概按照元祖的定义来说也符合的，"}, {"start": 109.9, "end": 113.9, "reading": "一番(いちばん)岩(いわ)草(くさ)としてふさわしいお店(みせ)なのではないかと思わ(おもわ)れます。", "zh": "可以认为是最适合称为元祖的店。"}, {"start": 113.9, "end": 115.9, "reading": "そしてこれから紹介(しょうかい)する、", "zh": "然后接下来要介绍的，"}, {"start": 115.9, "end": 119.9, "reading": "二つ(ふたつ)の岩(いわ)草(くさ)ラーメン長浜(ながはま)居(きょ)へとは関係(かんけい)がないということを", "zh": "这家店说，和两家元祖拉面长滨屋没有关系。"}, {"start": 119.9, "end": 121.9, "reading": "このお店(みせ)が言って(いって)るんだそうです。", "zh": "据说是这家店在这么说。"}, {"start": 121.9, "end": 124.9, "reading": "この岩(いわ)草(くさ)長浜(ながはま)奥(おく)から、", "zh": "从这家元祖长滨屋，"}, {"start": 124.9, "end": 126.9, "reading": "その従業員(じゅうぎょういん)の人(にん)がですね、", "zh": "那里的员工呢，"}, {"start": 126.9, "end": 129.9, "reading": "一人(ひとり)独立(どくりつ)してラーメン屋(や)をこの近く(ちかく)に開い(ひらい)たらしいんですね。", "zh": "据说有一个人独立出来，在这附近开了拉面店。"}, {"start": 129.9, "end": 131.9, "reading": "それが将来(しょうらい)と言い(いい)ますか、", "zh": "那个说是将来也好，"}, {"start": 131.9, "end": 134.9, "reading": "一つ目(ひとつめ)の岩(いわ)草(くさ)ラーメン長浜(ながはま)居(きょ)へなんですけど、", "zh": "就是第一家元祖拉面长滨屋，"}, {"start": 134.9, "end": 137.9, "reading": "岩(いわ)草(くさ)を名乗っ(なのっ)ているのだけれども、", "zh": "虽然自称元祖，"}, {"start": 137.9, "end": 139.9, "reading": "岩(いわ)草(くさ)長浜屋(ながはまや)の視点(してん)ではないんですよ。", "zh": "却不是元祖长滨屋的观点。"}, {"start": 139.9, "end": 141.9, "reading": "長浜(ながはま)奥(おく)の視点(してん)ではない。", "zh": "不是长滨屋的观点。"}, {"start": 141.9, "end": 145.9, "reading": "ただつまり子供(こども)が勝手(かって)に岩(いわ)草(くさ)を名乗り(なのり)始め(はじめ)たら、", "zh": "只是也就是说，如果孩子擅自开始自称元祖，"}, {"start": 145.9, "end": 147.9, "reading": "ちょっとこれは良く(よく)ないんじゃないかなと思い(おもい)ますね。", "zh": "我觉得这有点不太好吧。"}, {"start": 147.9, "end": 149.9, "reading": "そしたらですね、なんと、", "zh": "这样一来呢，居然，"}, {"start": 149.9, "end": 152.9, "reading": "子供(こども)岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)の", "zh": "孩子元祖拉面长滨屋的"}, {"start": 152.9, "end": 154.9, "reading": "その従業員(じゅうぎょういん)の一人(ひとり)がですね、", "zh": "那里的一个员工呢，"}, {"start": 154.9, "end": 157.9, "reading": "なんか方針(ほうしん)の違い(ちがい)で喧嘩別(けんかべつ)れしたみたいな感じ(かんじ)らしいんですけど、", "zh": "据说好像是因为方针不同吵架分开了，"}, {"start": 157.9, "end": 162.9, "reading": "その従業員(じゅうぎょういん)が岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)という同じ(おなじ)名前(なまえ)で", "zh": "那个员工用元祖拉面长滨屋这个同样的名字，"}, {"start": 162.9, "end": 165.9, "reading": "そのすぐまた近く(ちかく)にお店(みせ)を作っ(つくっ)たのだそうです。", "zh": "据说又在那附近开了店。"}, {"start": 165.9, "end": 167.9, "reading": "そしたらなんとですね、", "zh": "这样一来居然呢，"}, {"start": 167.9, "end": 171.9, "reading": "岩(いわ)草(くさ)の方が(ほうが)孫(まご)にあたる同じ(おなじ)名前(なまえ)の岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)を", "zh": "元祖这一方把相当于孙子的同名的元祖拉面长滨屋"}, {"start": 171.9, "end": 174.9, "reading": "訴え(うったえ)たんですね、こんな名前(なまえ)を勝手(かって)に使う(つかう)なと言って(いって)。", "zh": "告上了法庭，说不要擅自使用这样的名字。"}, {"start": 174.9, "end": 177.9, "reading": "一方(いっぽう)で孫(まご)の方(ほう)にも言い分(いいぶん)があって、", "zh": "另一方面孙子那边也有他们的说法，"}, {"start": 177.9, "end": 182.9, "reading": "自分(じぶん)の孫(まご)からして親(おや)、つまり初代(しょだい)岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)の", "zh": "据说从自己的孙子来看是父母，也就是初代元祖拉面长滨屋的"}, {"start": 182.9, "end": 187.9, "reading": "店(みせ)の人(にん)から岩(いわ)草(くさ)長浜屋(ながはまや)という野(の)郷(さと)を使って(つかって)もいいよ", "zh": "店里的人，被允许使用元祖长滨屋这个屋号。"}, {"start": 187.9, "end": 189.9, "reading": "ということを許さ(ゆるさ)れていたんだそうです。", "zh": "据说是这样被允许的。"}, {"start": 189.9, "end": 193.9, "reading": "そこに長浜屋(ながはまや)と入れ(いれ)たのは確かに(たしかに)孫(まご)が勝手(かって)にやったらしいんですが、", "zh": "在那里加入长滨屋，确实好像是孙子擅自做的，"}, {"start": 193.9, "end": 197.9, "reading": "どっちだって一緒(いっしょ)だろうと言って(いって)、岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)", "zh": "说反正哪边都一样吧，元祖拉面长滨屋"}, {"start": 197.9, "end": 203.9, "reading": "孫(まご)にあたるところは結局(けっきょく)廃(はい)走と(はしと)いうことになったのでした。", "zh": "相当于孙子的那家最终就变成败诉了。"}, {"start": 203.9, "end": 208.9, "reading": "そんなわけで岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)は登録(とうろく)消去(しょうきょ)なんて書か(かか)けてますけど", "zh": "就这样，元祖拉面长滨屋虽然写着注册注销，"}, {"start": 208.9, "end": 210.9, "reading": "今(いま)でもあそこで元気(げんき)に営業(えいぎょう)しています。", "zh": "现在也仍然在那里精神地营业着。"}, {"start": 210.9, "end": 212.9, "reading": "ラーメンはとても美味しい(おいしい)んだと思い(おもい)ますよ。", "zh": "我想拉面是非常好吃的哦。"}, {"start": 212.9, "end": 216.9, "reading": "ところがこの辺り(あたり)には他に(ほかに)もそれらの物(もの)とは", "zh": "可是在这一带还有其他和那些东西，"}, {"start": 216.9, "end": 219.9, "reading": "一連(いちれん)の流れ(ながれ)とは関係(かんけい)のない普通(ふつう)のラーメン屋(や)さんがあるんですが", "zh": "和一连串经过没有关系的普通的拉面店，"}, {"start": 219.9, "end": 222.9, "reading": "ここにも岩(いわ)草(くさ)長浜屋(ながはまや)って書い(かい)てあって", "zh": "这里也写着元祖长滨屋，然后"}, {"start": 222.9, "end": 224.9, "reading": "長浜(ながはま)将軍(しょうぐん)というラーメン屋(や)がありますけど", "zh": "虽然有一家叫长滨将军的拉面店"}, {"start": 224.9, "end": 227.9, "reading": "上(うえ)を見る(みる)と岩(いわ)草(くさ)はかた長浜(ながはま)と書い(かい)てあります。", "zh": "往上看的话，写着岩草博多长滨。"}, {"start": 227.9, "end": 230.9, "reading": "岩(いわ)草(くさ)と書い(かい)てるラーメン屋(や)がいっぱいあるんですね。", "zh": "写着岩草的拉面店有很多呢。"}, {"start": 230.9, "end": 231.9, "reading": "あの子(こ)めちゃくちゃな。", "zh": "那孩子乱七八糟的。"}, {"start": 231.9, "end": 233.9, "reading": "これがそのラーメンエリアなんですけどね。", "zh": "这就是那个拉面区域了。"}, {"start": 233.9, "end": 235.9, "reading": "今(いま)私(わたし)が居た(いた)ところこの辺(へん)なんですけど", "zh": "现在我所在的地方是这一带，"}, {"start": 235.9, "end": 237.9, "reading": "ここはそもそも長浜(ながはま)というところで", "zh": "这里本来就是叫长滨的地方，"}, {"start": 237.9, "end": 241.9, "reading": "あのはかたというははかたとはね絶対(ぜったい)呼ば(よば)ないんですよなのに", "zh": "那个，博多这个地方，绝对不会叫作博多，可是却"}], "4": [{"start": 0.0, "end": 4.0, "reading": "岩(いわ)草(くさ)はかた長浜(ながはま)なんてめちゃくちゃなことを名乗る(なのる)店(みせ)まであります。", "zh": "甚至有店自称岩草博多长滨这种乱七八糟的名字。"}, {"start": 4.0, "end": 7.0, "reading": "近(きん)手に(てに)乗って(のって)移動(いどう)するのは中(なか)スカーワタです。", "zh": "乘坐近手移动的是中斯卡瓦塔。"}, {"start": 7.0, "end": 10.0, "reading": "ここにあるラーメン屋(や)で食べ(たべ)ようと思い(おもい)ます。", "zh": "我打算在这里的拉面店吃。"}, {"start": 10.0, "end": 12.0, "reading": "ここに行く(いく)と思い(おもい)ます。", "zh": "我想会去这里。"}, {"start": 12.0, "end": 14.0, "reading": "さっきあそこでね喧嘩(けんか)してたお店(みせ)とか", "zh": "刚才在那边吵架的店啊，"}, {"start": 14.0, "end": 16.0, "reading": "あの岩(いわ)草(くさ)の流れ(ながれ)を組む(くむ)お店(みせ)とか", "zh": "还有承接那个岩草一脉的店啊，"}, {"start": 16.0, "end": 19.0, "reading": "そういうところに行け(いけ)ばいいと思う(おもう)じゃないですか。", "zh": "你不是会觉得去那样的地方就好了吗。"}, {"start": 19.0, "end": 21.0, "reading": "ここには岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)が", "zh": "在这里有岩草拉面长滨屋，"}, {"start": 21.0, "end": 25.0, "reading": "その裁判(さいばん)で負け(まけ)た岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)が移転(いてん)してきたのです。", "zh": "那家在那场官司中败诉的岩草拉面长滨屋搬迁到了这里。"}, {"start": 25.0, "end": 28.0, "reading": "なんで移転(いてん)してきたかはね全く(まったく)わかりませんけど", "zh": "为什么搬迁过来，完全不知道，"}, {"start": 28.0, "end": 33.0, "reading": "まぁ裁判(さいばん)までやって負け(まけ)たらもうあの辺(へん)にいずらくなったのかなーなんて", "zh": "嘛，打了官司还输了，是不是变得在那一带待不下去了呢，"}, {"start": 33.0, "end": 35.0, "reading": "思わ(おもわ)なくもありません。", "zh": "也不是没有这样想。"}, {"start": 35.0, "end": 38.0, "reading": "この辺り(あたり)は逆に(ぎゃくに)長浜(ながはま)という地区(ちく)ではなく", "zh": "这一带反而不是叫长滨的地区，"}, {"start": 39.0, "end": 42.0, "reading": "ここは完全(かんぜん)に測っ(はかっ)たですね中川(なかがわ)を渡っ(わたっ)た", "zh": "这里完全是测的塔呢，是渡过中川之后的"}, {"start": 42.0, "end": 44.0, "reading": "川(かわ)の中須(なかす)の近く(ちかく)です。", "zh": "川的中洲的附近。"}, {"start": 44.0, "end": 46.6, "reading": "ありました。", "zh": "找到了。"}, {"start": 46.6, "end": 48.6, "reading": "岩(いわ)草(くさ)ラーメン長浜屋(ながはまや)", "zh": "岩草拉面长滨屋"}, {"start": 48.6, "end": 53.6, "reading": "もう全然(ぜんぜん)所在地(しょざいち)は長浜(ながはま)のうお市場(しじょう)の近く(ちかく)ではなくなってしまいましたが", "zh": "所在地已经完全不在长滨的鱼市场附近了，"}, {"start": 53.6, "end": 56.6, "reading": "しかし外(そと)にはおいしそうな匂い(におい)を漂わ(ただよわ)せて", "zh": "但是外面飘着看起来很好吃的香味，"}, {"start": 56.6, "end": 58.6, "reading": "煙(けむり)が流れ(ながれ)てきてますよ。", "zh": "烟正在飘过来哦。"}, {"start": 58.6, "end": 61.6, "reading": "岩(いわ)草(くさ)という言葉(ことば)の意味(いみ)は", "zh": "岩草这个词的意思，"}, {"start": 61.6, "end": 63.6, "reading": "もう一度(いちど)考え(かんがえ)ておくべきかもしれないですね。", "zh": "或许应该再想一想呢。"}, {"start": 63.6, "end": 64.6, "reading": "すぐにラーメンが出て(でて)きました。", "zh": "拉面马上就出来了。"}, {"start": 64.6, "end": 65.6, "reading": "肉(にく)がドスタリ乗って(のって)います。", "zh": "肉沉甸甸地放在上面。"}, {"start": 65.6, "end": 66.6, "reading": "ネギもドスタリです。", "zh": "葱也是沉甸甸的。"}, {"start": 66.6, "end": 67.6, "reading": "これはおいしそう。", "zh": "这个看起来很好吃。"}, {"start": 67.6, "end": 68.6, "reading": "とてもおいしかった。", "zh": "非常好吃。"}, {"start": 69.6, "end": 70.6, "reading": "豚骨(とんこつ)ラーメンというと", "zh": "说到豚骨拉面的话，"}, {"start": 70.6, "end": 71.6, "reading": "すごい脂っこい(あぶらっこい)というイメージです。", "zh": "是非常油腻的印象。"}, {"start": 71.6, "end": 73.6, "reading": "私(わたし)は横浜(よこはま)岩(いわ)草(くさ)ラーメンってのね", "zh": "我是横滨岩草拉面这个啊，"}, {"start": 73.6, "end": 75.6, "reading": "よく大学(だいがく)の近く(ちかく)で売っ(うっ)てるのを見ま(みま)すけど", "zh": "常在大学附近看到有卖，"}, {"start": 75.6, "end": 76.6, "reading": "お腹(はら)壊し(こわし)たいそうなんで", "zh": "因为好像会把肚子吃坏"}, {"start": 76.6, "end": 77.6, "reading": "あんま食べ(たべ)ないんですが", "zh": "不太吃"}, {"start": 78.6, "end": 79.6, "reading": "福岡(ふくおか)のラーメンはね", "zh": "福冈的拉面呢"}, {"start": 79.6, "end": 81.6, "reading": "そんなに脂っこく(あぶらっこく)ないんですよ。", "zh": "没有那么油腻啊"}, {"start": 81.6, "end": 83.6, "reading": "だから豚(ぶた)の骨(ほね)が", "zh": "所以猪的骨头"}, {"start": 83.6, "end": 84.6, "reading": "脚(あし)を取っ(とっ)てますけど", "zh": "去掉了脚"}, {"start": 84.6, "end": 87.6, "reading": "それだけでね結構(けっこう)スイスイ食べ(たべ)られてしまう", "zh": "光是那样呢就能相当轻松地吃下去"}, {"start": 87.6, "end": 89.6, "reading": "ずっと食べ(たべ)られた味(あじ)があって", "zh": "有一直能吃下去的味道"}, {"start": 89.6, "end": 91.6, "reading": "こういうタレみたいなものを作っ(つくっ)て", "zh": "做出像这种酱汁一样的东西"}, {"start": 91.6, "end": 93.6, "reading": "味を(あじを)減ら(へら)せたりします。", "zh": "也可以减少味道。"}, {"start": 93.6, "end": 94.6, "reading": "麺(めん)が非常に(ひじょうに)細い(こまい)のは", "zh": "面非常细是因为"}, {"start": 94.6, "end": 96.6, "reading": "早く(はやく)茹で(ゆで)られるように", "zh": "为了能够快速煮好"}, {"start": 96.6, "end": 98.6, "reading": "いちばんの中(なか)でささっと茹で(ゆで)て", "zh": "在最一番里飞快地煮一下"}, {"start": 98.6, "end": 99.6, "reading": "パッと食べて(たべて)また", "zh": "很快吃完又"}, {"start": 99.6, "end": 100.6, "reading": "いちばんの仕事(しごと)に戻る(もどる)", "zh": "回到最一番的工作"}, {"start": 100.6, "end": 101.6, "reading": "という人(にん)たちは", "zh": "这样的人们"}, {"start": 101.6, "end": 103.6, "reading": "需要(じゅよう)に応え(こたえ)たのだそうです。", "zh": "据说是回应了需求。"}, {"start": 103.6, "end": 105.6, "reading": "これですね仕事(しごと)の関係(かんけい)の方が(ほうが)", "zh": "这个呢和工作有关的人"}, {"start": 105.6, "end": 107.6, "reading": "私(わたし)のこれを取っ(とっ)てくれたんですけども", "zh": "帮我拍了这个"}, {"start": 107.6, "end": 109.6, "reading": "熱い(あつい)ラーメンをすすっている", "zh": "正在呼噜呼噜吸着热拉面的"}, {"start": 109.6, "end": 111.6, "reading": "私(わたし)の様子(ようす)です。", "zh": "我的样子。"}, {"start": 111.6, "end": 114.3, "reading": "こんな感じ(かんじ)でね", "zh": "就是这样呢"}, {"start": 115.3, "end": 116.3, "reading": "この岩(いわ)草(くさ)ラーメン", "zh": "这家岩草拉面"}, {"start": 116.3, "end": 117.3, "reading": "長浜(ながはま)家(いえ)って", "zh": "叫长滨家"}, {"start": 117.3, "end": 119.3, "reading": "あの裁判(さいばん)に負け(まけ)た店(みせ)", "zh": "那个官司输了的店"}, {"start": 119.3, "end": 120.3, "reading": "一気(いっき)見た(みた)わけですけど", "zh": "一口气看了"}, {"start": 120.3, "end": 122.3, "reading": "負け(まけ)た店(みせ)とは思え(おもえ)ないほどね", "zh": "但完全不像是输了官司的店啊"}, {"start": 122.3, "end": 123.3, "reading": "味(あじ)はもう大勝利(だいしょうり)でしたね。", "zh": "味道可以说是大获全胜呢。"}, {"start": 123.3, "end": 125.3, "reading": "多分(たぶん)大体(だいたい)のお客(きゃく)さんは", "zh": "大概大部分客人"}, {"start": 125.3, "end": 127.3, "reading": "そんなことも全く(まったく)気に(きに)しないと思う(おもう)んで", "zh": "应该完全不会在意那种事"}, {"start": 127.3, "end": 129.3, "reading": "美味しい(おいしい)ラーメンが出て(でて)くれば", "zh": "所以只要端出好吃的拉面"}, {"start": 129.3, "end": 131.3, "reading": "もうそれでいいんじゃないですか?", "zh": "那不就已经足够了吗?"}, {"start": 131.3, "end": 134.1, "reading": "僕(ぼく)でなんかグルグルやってますね", "zh": "我这边不知怎么在咕噜咕噜地弄着呢"}, {"start": 134.1, "end": 136.1, "reading": "これ店(みせ)の外(そと)から撮影(さつえい)したものですけど", "zh": "这是从店外拍摄的"}, {"start": 137.1, "end": 139.1, "reading": "うまそうだラーメンだ", "zh": "看起来好吃啊是拉面啊"}, {"start": 139.1, "end": 141.1, "reading": "実は(じつは)さっき寿司(すし)をたらふく食べて(たべて)いたので", "zh": "其实刚才寿司吃了个饱"}, {"start": 141.1, "end": 142.1, "reading": "本当(ほんとう)はお代わり(かわり)したかったんですが", "zh": "本来想再添一碗的"}, {"start": 142.1, "end": 143.1, "reading": "もう満腹(まんぷく)で", "zh": "但已经吃饱了"}, {"start": 143.1, "end": 145.1, "reading": "これ以上(いじょう)は食べ(たべ)ることができませんでした。", "zh": "再多就吃不下了。"}, {"start": 146.1, "end": 148.1, "reading": "かってその後(のち)", "zh": "然后之后"}, {"start": 149.1, "end": 151.1, "reading": "泣か(なか)せの商店街(しょうてんがい)を抜け(ぬけ)て", "zh": "穿过泣かせ的商店街"}, {"start": 151.1, "end": 152.1, "reading": "大き(おおき)なダッシュみたいなのがありますね", "zh": "有一个像大冲刺一样的东西呢"}, {"start": 152.1, "end": 154.1, "reading": "ユネスコの無形(むけい)文化(ぶんか)遺産(いさん)", "zh": "联合国教科文组织的非物质文化遗产"}, {"start": 154.1, "end": 155.1, "reading": "最近(さいきん)こういうダッシュ行列(ぎょうれつ)が", "zh": "最近这样的冲刺队列"}, {"start": 155.1, "end": 157.1, "reading": "登録(とうろく)されたそうですけども", "zh": "据说已经被登录了"}, {"start": 157.1, "end": 159.1, "reading": "このクシダ神社(じんじゃ)の行列(ぎょうれつ)が", "zh": "这个串田神社的队列"}, {"start": 159.1, "end": 162.1, "reading": "また大変有名(たいへんゆうめい)なお祭り(まつり)なんだそうです", "zh": "又是非常有名的祭典的样子"}, {"start": 162.1, "end": 164.1, "reading": "毎年(まいとし)5月(がつ)とかだったと思う(おもう)んですが", "zh": "每年5月之类的时候我记得"}, {"start": 164.1, "end": 165.1, "reading": "初夏(しょか)の時期(じき)になると", "zh": "到了初夏的时期"}, {"start": 165.1, "end": 166.1, "reading": "墓田(はかた)のこのあたりでは", "zh": "在墓田的这一带"}, {"start": 166.1, "end": 168.1, "reading": "なんでもお祭り(まつり)をやる人(にん)たちが", "zh": "听说无论如何举办祭典的人们"}, {"start": 168.1, "end": 170.1, "reading": "もうみんなお祭り(まつり)が大好き(だいすき)でね", "zh": "大家都非常喜欢祭典呢"}, {"start": 170.1, "end": 172.1, "reading": "ふんどし一丁(いっちょう)の姿(すがた)で", "zh": "以只穿一条兜裆布的样子"}, {"start": 172.1, "end": 173.1, "reading": "なんかうろろしたりとか", "zh": "好像会到处晃来晃去"}, {"start": 173.1, "end": 175.1, "reading": "するらしいという話(はなし)を聞き(きき)ました", "zh": "我听到了这样的说法"}, {"start": 177.1, "end": 178.1, "reading": "これでこちら", "zh": "那么这边"}, {"start": 178.1, "end": 180.1, "reading": "マロシンスイスなんと書い(かい)てあって", "zh": "丸新水产，写着这样的字"}, {"start": 180.1, "end": 182.1, "reading": "何(なに)やら水槽(すいそう)を積ん(つん)だような自動車(じどうしゃ)が来て(きて)いますね", "zh": "有一辆像是装了水槽的汽车过来了呢"}, {"start": 182.1, "end": 184.1, "reading": "これね聞い(きい)たらこの中に(なかに)", "zh": "这个呢，我问了，说这里面"}, {"start": 184.1, "end": 186.1, "reading": "イカがいるんだそうです", "zh": "有乌贼的样子"}, {"start": 186.1, "end": 188.1, "reading": "生き(いき)ているイカをそのまま捌(はち)いて", "zh": "把活着的乌贼就那样切开"}, {"start": 188.1, "end": 190.1, "reading": "新鮮(しんせん)だから動い(うごい)た状態(じょうたい)で", "zh": "因为新鲜所以在动的状态下"}, {"start": 190.1, "end": 192.1, "reading": "食べ(たべ)るみたいなイカの踊り(おどり)食い(くい)というのが", "zh": "吃的那种乌贼的活吃叫做"}, {"start": 192.1, "end": 194.1, "reading": "ありますけれど", "zh": "有是有"}, {"start": 194.1, "end": 196.1, "reading": "それができるおそらくは", "zh": "能做那个的大概"}, {"start": 196.1, "end": 198.1, "reading": "そのためにあいたものを", "zh": "为此把相遇的东西"}, {"start": 198.1, "end": 200.1, "reading": "わざわざ水槽(すいそう)を運ん(はこん)できたりしているんでしょう", "zh": "特意搬运水槽过来吧"}, {"start": 200.1, "end": 202.1, "reading": "福岡(ふくおか)にはいろんな芽(め)物(もの)があり", "zh": "福冈有各种各样的美味的东西"}, {"start": 202.1, "end": 204.1, "reading": "まだまだ紹介(しょうかい)しきれてはいません", "zh": "还远远没有介绍完"}, {"start": 204.1, "end": 206.1, "reading": "こちらのナカスカーバターの", "zh": "这边的中洲巴特的"}, {"start": 206.1, "end": 208.1, "reading": "ちょっとなんか危ない(あぶない)ようなエリアですね", "zh": "有点好像危险的区域呢"}, {"start": 208.1, "end": 209.1, "reading": "怖そ(こわそ)うな人(にん)とかね", "zh": "看起来可怕的人啊"}, {"start": 209.1, "end": 210.1, "reading": "なんか不審(ふしん)な高級(こうきゅう)者(もの)とかが", "zh": "有可疑的高级车之类的"}, {"start": 210.1, "end": 211.1, "reading": "止ま(とま)ってて", "zh": "停着"}, {"start": 211.1, "end": 213.1, "reading": "なんだわりだと思い(おもい)ましたよ", "zh": "我觉得挺什么的"}, {"start": 213.1, "end": 214.1, "reading": "猫(ねこ)はそんなこと知ら(しら)ないかな", "zh": "猫是不知道那种事的吧"}, {"start": 214.1, "end": 216.1, "reading": "いやあの猫(ねこ)なら知って(しって)いるでしょうね", "zh": "不，那只猫的话是知道的吧"}, {"start": 216.1, "end": 218.1, "reading": "きっとナカスカーバターの", "zh": "一定是中洲巴特的"}, {"start": 218.1, "end": 219.1, "reading": "ナカスの裏(うら)の裏(うら)まで", "zh": "中洲的里里外外"}, {"start": 219.1, "end": 220.1, "reading": "あの猫(ねこ)は見て(みて)きているけれども", "zh": "那只猫都已经看过了但是"}, {"start": 220.1, "end": 222.1, "reading": "何も(なにも)知ら(しら)ないきれいに", "zh": "什么都不知道地干净地"}, {"start": 222.1, "end": 224.1, "reading": "違い(ちがい)ありません", "zh": "肯定没错"}, {"start": 224.1, "end": 225.1, "reading": "バニラ", "zh": "香草"}, {"start": 225.1, "end": 227.1, "reading": "公衆(こうしゅう)に弾(だん)突(とつ)ナンバーワン", "zh": "公众弹突第一名"}, {"start": 227.1, "end": 228.1, "reading": "ああいう看板(かんばん)を見る(みる)とね", "zh": "看到那样的招牌的话呢"}, {"start": 228.1, "end": 230.1, "reading": "ああ大都会(だいとかい)だなという感じ(かんじ)がしますね", "zh": "啊，有种大都会的感觉呢"}, {"start": 230.1, "end": 232.1, "reading": "だってそれからは", "zh": "因为，从那之后"}, {"start": 232.1, "end": 233.1, "reading": "もうそろそろ仕事(しごと)の時間(じかん)が", "zh": "已经快到工作的时间了"}, {"start": 233.1, "end": 234.1, "reading": "近づ(ちかづ)いてきているんですけど", "zh": "正在临近"}, {"start": 234.1, "end": 235.1, "reading": "まだ時間(じかん)に余裕(よゆう)があったので", "zh": "不过还有时间的余裕"}, {"start": 235.1, "end": 236.1, "reading": "じゃあちょっと", "zh": "那么稍微"}, {"start": 236.1, "end": 237.1, "reading": "面白い(おもしろい)ところに行こ(いこ)うと思う(おもう)", "zh": "想去有趣的地方"}, {"start": 237.1, "end": 239.1, "reading": "地下鉄(ちかてつ)の西人(せいじん)駅(えき)で降り(おり)てから", "zh": "从地铁的西人站下车之后"}, {"start": 239.1, "end": 241.1, "reading": "しばらく歩い(あるい)て", "zh": "走了一会儿"}], "5": [{"start": 0.0, "end": 2.0, "reading": "向こう(むこう)に見え(みえ)ているタワーへ向か(むか)うことに", "zh": "决定朝着对面看得见的塔前进"}, {"start": 2.0, "end": 3.0, "reading": "しました", "zh": "了"}, {"start": 3.0, "end": 4.0, "reading": "一瞬(いっしゅん)でなんか切れ(きれ)ちゃいましたね", "zh": "一瞬间不知怎么就中断了呢"}, {"start": 4.0, "end": 5.0, "reading": "映像(えいぞう)がすいません", "zh": "影像很抱歉"}, {"start": 5.0, "end": 6.0, "reading": "あれしか撮っ(とっ)てなかったんですけど", "zh": "只拍了那个而已"}, {"start": 6.0, "end": 8.0, "reading": "福岡(ふくおか)タワーです", "zh": "是福冈塔"}, {"start": 8.0, "end": 10.0, "reading": "福岡市(ふくおかし)で一番(いちばん)高い(たかい)建物(たてもの)は", "zh": "福冈市最高的建筑物是"}, {"start": 10.0, "end": 12.0, "reading": "これですかね", "zh": "是这个吧"}, {"start": 12.0, "end": 14.0, "reading": "私(わたし)ちゃんと確認し(かくにんし)てないんですが", "zh": "我没有好好确认过"}, {"start": 14.0, "end": 16.0, "reading": "福岡市(ふくおかし)は福岡空港(ふくおかくうこう)がある関係(かんけい)で", "zh": "福冈市因为有福冈机场的关系"}, {"start": 16.0, "end": 18.0, "reading": "高さ(たかさ)制限(せいげん)があって", "zh": "有高度限制"}, {"start": 18.0, "end": 20.0, "reading": "あまり高い(たかい)ものを建て(たて)ることができないんだそうです", "zh": "据说不能建造太高的东西"}, {"start": 22.0, "end": 24.0, "reading": "このタワーの入場料(にゅうじょうりょう)金(きん)は800円(えん)", "zh": "这座塔的入场费是800日元"}, {"start": 24.0, "end": 26.0, "reading": "この手の(ての)タワーにしては", "zh": "作为这类塔来说"}, {"start": 26.0, "end": 28.0, "reading": "ちょっと休め(やすめ)だと思い(おもい)ますけど", "zh": "我觉得稍微算便宜的"}, {"start": 28.0, "end": 30.0, "reading": "これなんか国際会議(こくさいかいぎ)をやった時(とき)", "zh": "这个好像是举办国际会议的时候"}, {"start": 30.0, "end": 32.0, "reading": "そのシングルとして建て(たて)たんだそうですね", "zh": "作为那个的单身而建造的"}, {"start": 32.0, "end": 37.7, "reading": "ガラスバリンのデザインで", "zh": "玻璃玻璃的设计"}, {"start": 37.7, "end": 38.7, "reading": "上(うえ)からエレベーターが降り(おり)てきました", "zh": "电梯从上面下来了"}, {"start": 38.7, "end": 39.7, "reading": "結構(けっこう)たくさん人(にん)がいました", "zh": "相当多的人在"}, {"start": 39.7, "end": 40.7, "reading": "やっぱり年末(ねんまつ)ですから", "zh": "果然因为是年末"}, {"start": 40.7, "end": 41.7, "reading": "観光(かんこう)の人(にん)がいっぱい", "zh": "观光的人很多"}, {"start": 41.7, "end": 43.7, "reading": "でも中国(ちゅうごく)観光(かんこう)の人(にん)が", "zh": "不过中国观光的人"}, {"start": 43.7, "end": 44.7, "reading": "やっぱり多か(おおか)ったですね", "zh": "果然还是很多呢"}, {"start": 44.7, "end": 46.7, "reading": "福岡(ふくおか)は海内(かいだい)からの観光局(かんこうきょく)が", "zh": "福冈来自海内的观光局"}, {"start": 46.7, "end": 48.7, "reading": "特に(とくに)目立つ(めだつ)ところでもあります", "zh": "也是特别显眼的地方"}, {"start": 48.7, "end": 52.9, "reading": "福岡(ふくおか)タワーの最上階(さいじょうかい)は", "zh": "福冈塔的最顶层是"}, {"start": 52.9, "end": 54.9, "reading": "ビルの高さ(たかさ)にいたしますと", "zh": "以大楼的高度来说"}, {"start": 54.9, "end": 57.9, "reading": "約(やく)40階(かい)に相当(そうとう)いたします", "zh": "相当于大约40层"}, {"start": 57.9, "end": 59.9, "reading": "で一番上(いちばんうえ)のところまで上が(あが)ってきました", "zh": "然后已经爬到最上面的地方了"}, {"start": 59.9, "end": 60.9, "reading": "ここが", "zh": "这里是"}, {"start": 60.9, "end": 62.9, "reading": "福岡(ふくおか)はかた方面(ほうめん)の長め(ながめ)です", "zh": "福冈博多方面的景色"}, {"start": 62.9, "end": 63.9, "reading": "パッと見て(みて)", "zh": "一眼看去"}, {"start": 63.9, "end": 65.9, "reading": "ウォォォォォォォォォォ", "zh": "哇哦哦哦哦哦哦哦哦"}, {"start": 65.9, "end": 66.9, "reading": "そういう長め(ながめ)は", "zh": "那样的景色"}, {"start": 66.9, "end": 68.9, "reading": "そんなのではないかなと思う(おもう)んですが", "zh": "我想大概就是那样的吧"}, {"start": 68.9, "end": 69.9, "reading": "あそこにね", "zh": "在那边呢"}, {"start": 69.9, "end": 70.9, "reading": "ハカタ港(みなと)があります", "zh": "有博多港"}, {"start": 70.9, "end": 71.9, "reading": "ちょっと手前(てまえ)", "zh": "稍微靠前一点"}, {"start": 71.9, "end": 73.9, "reading": "砂浜(すなはま)の少し(すこし)ばかり", "zh": "沙滩的稍微"}, {"start": 73.9, "end": 75.9, "reading": "奥(おく)のところが長浜(ながはま)港(みなと)だったんですが", "zh": "里面的地方是长滨港，不过"}, {"start": 75.9, "end": 76.9, "reading": "このハカタ港(みなと)は", "zh": "这个博多港"}, {"start": 76.9, "end": 78.9, "reading": "多分(たぶん)あすか時代(じだい)とか", "zh": "大概在飞鸟时代之类的"}, {"start": 78.9, "end": 79.9, "reading": "それぐらいには", "zh": "差不多那个时候"}, {"start": 79.9, "end": 81.9, "reading": "海外(かいがい)との貿易(ぼうえき)が始ま(はじま)っていた", "zh": "就已经开始了与海外的贸易"}, {"start": 81.9, "end": 82.9, "reading": "重要な(じゅうような)", "zh": "重要的"}, {"start": 82.9, "end": 85.9, "reading": "国際(こくさい)港(みなと)というべきですかね", "zh": "可以说是国际港口吧"}, {"start": 85.9, "end": 87.9, "reading": "現在(げんざい)でもJR九州(きゅうしゅう)の旅客(りょきゃく)船(ふね)", "zh": "现在也有JR九州的客船"}, {"start": 87.9, "end": 88.9, "reading": "ビートルとか", "zh": "比如Beetle（喷射水翼船）"}, {"start": 88.9, "end": 89.9, "reading": "それからプサ駅(えき)は他に(ほかに)も", "zh": "还有釜山站也是"}, {"start": 89.9, "end": 91.9, "reading": "フェリー・カメリアというのがあったと思う(おもう)んですが", "zh": "我记得还有渡轮茶花号"}, {"start": 91.9, "end": 93.9, "reading": "そういったまま出入り(でいり)しております", "zh": "就那样一直有进出"}, {"start": 93.9, "end": 95.9, "reading": "もちろん貿易(ぼうえき)の取扱い(とりあつかい)も", "zh": "当然贸易的处理也"}, {"start": 95.9, "end": 97.9, "reading": "今(いま)だってあるんでしょうね", "zh": "如今也有的吧"}, {"start": 97.9, "end": 99.9, "reading": "あのハカタの港(みなと)が発展(はってん)したことにより", "zh": "由于那个博多港的发展"}, {"start": 99.9, "end": 100.9, "reading": "その反対側(はんたいがわ)にある", "zh": "位于它另一侧的"}, {"start": 100.9, "end": 101.9, "reading": "なかすハカタも", "zh": "中洲博多也"}, {"start": 101.9, "end": 102.9, "reading": "超人(ちょうじん)の街(まち)として", "zh": "作为超人的街"}, {"start": 102.9, "end": 103.9, "reading": "坂(さか)へ", "zh": "坂へ"}, {"start": 103.9, "end": 104.9, "reading": "現在(げんざい)にまで", "zh": "一直到现在"}, {"start": 104.9, "end": 106.9, "reading": "反映(はんえい)を続け(つづけ)ているというわけです", "zh": "持续繁荣着"}, {"start": 106.9, "end": 108.9, "reading": "だから大体(だいたい)その辺(へん)が", "zh": "所以大致那一带"}, {"start": 108.9, "end": 110.9, "reading": "やっぱり高い(たかい)ビルが目立つ(めだつ)ようですけれど", "zh": "果然高楼很显眼的样子，不过"}, {"start": 110.9, "end": 112.9, "reading": "でも福岡空港(ふくおかくうこう)のおかげで", "zh": "但是多亏了福冈机场"}, {"start": 112.9, "end": 113.9, "reading": "ビルの高さ(たかさ)は", "zh": "楼的高度"}, {"start": 113.9, "end": 115.9, "reading": "それほどは高く(たかく)なく", "zh": "并没有那么高"}, {"start": 115.9, "end": 116.9, "reading": "超(ちょう)大都会(だいとかい)という印象(いんしょう)は", "zh": "给人超级大都会的印象是"}, {"start": 116.9, "end": 117.9, "reading": "そこの街並(まちなみ)みまでが", "zh": "那里的街景也"}, {"start": 117.9, "end": 119.9, "reading": "遠い(とおい)ということもあって", "zh": "离得远的缘故"}, {"start": 119.9, "end": 120.9, "reading": "それほど", "zh": "那么"}, {"start": 120.9, "end": 126.9, "reading": "ここで見た(みた)限り(かぎり)では受け(うけ)ません", "zh": "从这里看的话不怎么吸引人"}, {"start": 126.9, "end": 128.9, "reading": "もうちょっとこのタワーが近け(ちかけ)ればね", "zh": "如果这座塔再近一点的话"}, {"start": 128.9, "end": 129.9, "reading": "中川(なかがわ)とか", "zh": "中川之类的"}, {"start": 129.9, "end": 130.9, "reading": "みかさ川(かわ)とか", "zh": "御笠川之类的"}, {"start": 130.9, "end": 132.9, "reading": "ハカタという街(まち)を展示(てんじ)する", "zh": "展示博多这座城市的"}, {"start": 132.9, "end": 134.9, "reading": "2つの川(かわ)を見る(みる)こともできたのかも", "zh": "也许还能看到两条河"}, {"start": 134.9, "end": 135.9, "reading": "もしれないんですが", "zh": "也说不定，不过"}, {"start": 135.9, "end": 136.9, "reading": "ただしかし", "zh": "但是"}, {"start": 136.9, "end": 137.9, "reading": "高い(たかい)ところへ来る(くる)と", "zh": "一来到高的地方"}, {"start": 137.9, "end": 138.9, "reading": "面白い(おもしろい)ものが見ら(みら)れます", "zh": "就能看到有趣的东西"}, {"start": 138.9, "end": 139.9, "reading": "海の中道(うみのなかみち)です", "zh": "是海之中道"}, {"start": 139.9, "end": 140.9, "reading": "これはね", "zh": "这个啊"}, {"start": 140.9, "end": 141.9, "reading": "陸(りく)系(けい)島(しま)なのかな", "zh": "是陆系岛吗"}, {"start": 141.9, "end": 142.9, "reading": "それとも", "zh": "还是"}, {"start": 142.9, "end": 143.9, "reading": "サスなのかちょっと", "zh": "是沙嘴呢，有点"}, {"start": 143.9, "end": 144.9, "reading": "分か(わか)んないですけど", "zh": "我不太清楚"}, {"start": 144.9, "end": 145.9, "reading": "このような", "zh": "像这样的"}, {"start": 145.9, "end": 146.9, "reading": "海(うみ)のところですね", "zh": "海的地方啊"}, {"start": 146.9, "end": 148.9, "reading": "天然(てんねん)の防(ぼう)派(は)艇(てい)のようにして", "zh": "像天然的防波堤一样"}, {"start": 148.9, "end": 149.9, "reading": "細く(こまく)", "zh": "细细地"}, {"start": 149.9, "end": 150.9, "reading": "取り(とり)囲む(かこむ)", "zh": "围绕着"}, {"start": 150.9, "end": 152.9, "reading": "変わ(かわ)った地形(ちけい)があります", "zh": "有着奇特的地形"}, {"start": 152.9, "end": 153.9, "reading": "飛行機(ひこうき)降り(おり)るときですね", "zh": "乘飞机降落的时候啊"}, {"start": 153.9, "end": 154.9, "reading": "いつも飛行機(ひこうき)で", "zh": "总是乘飞机"}, {"start": 154.9, "end": 156.9, "reading": "不(ふ)光(ひかり)核(かく)空港(くうこう)に降り(おり)るとき", "zh": "降落到福冈机场的时候"}, {"start": 156.9, "end": 157.9, "reading": "下(した)を見て(みて)ると", "zh": "往下看的话"}, {"start": 157.9, "end": 159.9, "reading": "あの絶対(ぜったい)これ見え(みえ)ますよ", "zh": "那个一定能看到这个"}, {"start": 159.9, "end": 160.9, "reading": "海の中道(うみのなかみち)の上(うえ)を", "zh": "在海之中道的上面"}, {"start": 160.9, "end": 161.9, "reading": "飛び(とび)越え(こえ)て降り(おり)てくるの", "zh": "飞越过去降落下来"}, {"start": 161.9, "end": 163.9, "reading": "私(わたし)の見た(みた)限り(かぎり)では", "zh": "就我所见"}, {"start": 163.9, "end": 164.9, "reading": "毎回(まいかい)見ら(みら)れますのでね", "zh": "每次都能看到，所以"}, {"start": 164.9, "end": 166.9, "reading": "是非(ぜひ)視聴者(しちょうしゃ)の皆さん(みなさん)も", "zh": "请各位观众也"}, {"start": 166.9, "end": 167.9, "reading": "これ楽し(たのし)んでみてください", "zh": "请试着享受一下这个"}, {"start": 167.9, "end": 168.9, "reading": "変わ(かわ)った地形(ちけい)ですよ", "zh": "是奇特的地形哦"}, {"start": 168.9, "end": 169.9, "reading": "面白い(おもしろい)", "zh": "有趣"}, {"start": 169.9, "end": 170.9, "reading": "その手前(てまえ)を走っ(はしっ)ているのが", "zh": "在它前面行驶的是"}, {"start": 170.9, "end": 172.9, "reading": "ボーイング929", "zh": "波音929"}, {"start": 172.9, "end": 174.9, "reading": "JR九州(きゅうしゅう)の高速(こうそく)旅客(りょきゃく)船(ふね)", "zh": "JR九州的高速客船"}, {"start": 174.9, "end": 175.9, "reading": "プサ駅(えき)のビートルです", "zh": "釜山站的Beetle号"}, {"start": 175.9, "end": 176.9, "reading": "今(いま)プサンから", "zh": "现在从釜山"}, {"start": 176.9, "end": 178.9, "reading": "ちょうど帰っ(かえっ)てきたところ", "zh": "刚刚回来"}, {"start": 178.9, "end": 181.4, "reading": "下見(したみ)ると", "zh": "往下看"}, {"start": 181.4, "end": 183.4, "reading": "あれは結婚式場(けっこんしきじょう)ですかね", "zh": "那个是婚礼会场吗"}, {"start": 183.4, "end": 184.4, "reading": "なんか", "zh": "总觉得"}, {"start": 184.4, "end": 185.4, "reading": "砂浜(すなはま)の上に(うえに)", "zh": "沙滩之上"}, {"start": 185.4, "end": 186.4, "reading": "こういう風(かぜ)なものがあります", "zh": "有这样的东西"}, {"start": 186.4, "end": 187.4, "reading": "昔(むかし)はね", "zh": "以前啊"}, {"start": 187.4, "end": 188.4, "reading": "このあたりも", "zh": "这一带也"}, {"start": 188.4, "end": 189.4, "reading": "工業(こうぎょう)排水(はいすい)とかで", "zh": "因为工业废水之类"}, {"start": 189.4, "end": 190.4, "reading": "かなり汚染(おせん)されていて", "zh": "受到相当严重的污染"}, {"start": 190.4, "end": 192.4, "reading": "とても海(うみ)で泳げ(およげ)るような", "zh": "据说曾是完全不能在海里游泳的"}, {"start": 192.4, "end": 193.4, "reading": "状態(じょうたい)ではなかったそうですが", "zh": "状态"}, {"start": 193.4, "end": 194.4, "reading": "今(いま)では綺麗(きれい)な", "zh": "但现在有漂亮的"}, {"start": 194.4, "end": 196.4, "reading": "結婚式場(けっこんしきじょう)まであるそうです", "zh": "据说甚至还有婚礼会场"}, {"start": 196.4, "end": 200.5, "reading": "さてここにも", "zh": "那么这里也"}, {"start": 200.5, "end": 201.5, "reading": "私(わたし)のコレクションをしている", "zh": "我在收集的"}, {"start": 201.5, "end": 203.5, "reading": "記念(きねん)メダルがありましたんで", "zh": "有纪念徽章"}, {"start": 203.5, "end": 206.5, "reading": "早速(さっそく)本日(ほんじつ)の日付(ひづけ)を国(くに)員(いん)", "zh": "所以马上把今天的日期国员"}, {"start": 206.5, "end": 216.3, "reading": "本日(ほんじつ)は2019年(ねん)", "zh": "今天是2019年"}, {"start": 216.3, "end": 217.3, "reading": "10月(がつ)の30日(にち)でした", "zh": "10月30日"}, {"start": 217.3, "end": 218.3, "reading": "まあその方わ(ほうわ)かってますね", "zh": "嗯，那位是懂的呢"}, {"start": 218.3, "end": 220.3, "reading": "なかなかいいデザインですが", "zh": "设计相当不错"}, {"start": 220.3, "end": 222.3, "reading": "どっかで見た(みた)ことある形(かたち)だなと思った(おもった)ら", "zh": "心想是不是在哪里见过的形状"}, {"start": 222.3, "end": 223.3, "reading": "これね", "zh": "这个啊"}, {"start": 223.3, "end": 225.3, "reading": "ニューヨークの貿易(ぼうえき)センタービル", "zh": "纽约的贸易中心大楼"}, {"start": 225.3, "end": 227.3, "reading": "新しく(あたらしく)建て(たて)直し(なおし)た", "zh": "重新建造的"}, {"start": 227.3, "end": 229.3, "reading": "ワン・ワールドトレードセンターに", "zh": "One World Trade Center"}, {"start": 229.3, "end": 231.3, "reading": "そっくりなんですよね", "zh": "简直一模一样"}, {"start": 233.3, "end": 236.3, "reading": "高さ(たかさ)は234メートルって書い(かい)てあったかな", "zh": "高度写着是234米来着"}, {"start": 237.3, "end": 238.3, "reading": "そんなにやっぱり", "zh": "没有那么"}, {"start": 238.3, "end": 240.3, "reading": "高い(たかい)ブルーには入り(いり)ません", "zh": "高的蓝不属于其中"}], "6": [{"start": 3.0, "end": 4.0, "reading": "それからね", "zh": "然后呢"}, {"start": 4.0, "end": 5.0, "reading": "こういうところでよくあれや", "zh": "在这种地方经常那个"}, {"start": 5.0, "end": 6.0, "reading": "パターンですけど", "zh": "是个模式"}, {"start": 6.0, "end": 8.0, "reading": "上に(うえに)建物(たてもの)に行く(いく)時(とき)とかに", "zh": "上到建筑物的时候之类"}, {"start": 8.0, "end": 9.0, "reading": "写真(しゃしん)をこう撮っ(とっ)て", "zh": "把照片这样拍下来"}, {"start": 9.0, "end": 10.0, "reading": "後で(あとで)お金払っ(かねばらっ)て", "zh": "之后付钱"}, {"start": 10.0, "end": 11.0, "reading": "買い(かい)ませんか?", "zh": "要不要买呢?"}, {"start": 12.0, "end": 13.0, "reading": "買わ(かわ)なかったんですが", "zh": "虽然没有买"}, {"start": 13.0, "end": 14.0, "reading": "自分一人(じぶんひとり)で撮っ(とっ)た写真(しゃしん)", "zh": "自己一个人拍的照片"}, {"start": 14.0, "end": 15.0, "reading": "よく見て(みて)みると", "zh": "仔细看了看之后"}, {"start": 15.0, "end": 17.0, "reading": "ちょっとこの写真(しゃしん)は怖い(こわい)な", "zh": "这张照片有点可怕啊"}, {"start": 17.0, "end": 20.0, "reading": "横(よこ)のお寿司(すし)と影(かげ)男(おとこ)みたいな", "zh": "和旁边的寿司、像影子男人一样的东西"}, {"start": 20.0, "end": 22.0, "reading": "ちょっとこれは見て(みて)いても", "zh": "有点这个就算看着"}, {"start": 22.0, "end": 24.0, "reading": "気分(きぶん)が休ま(やすま)るものではありませんよね", "zh": "也不是能让心情放松的东西呢"}, {"start": 24.0, "end": 26.0, "reading": "この後(のち)はここからタクシーに乗って(のって)", "zh": "这之后从这里乘坐出租车"}, {"start": 26.0, "end": 28.0, "reading": "仕事(しごと)へ向かい(むかい)ました", "zh": "前往了工作的地方"}, {"start": 29.0, "end": 30.0, "reading": "仕事先(しごとさき)は結構(けっこう)いろいろ話(はなし)が", "zh": "工作的地方相当多的话题"}, {"start": 30.0, "end": 32.0, "reading": "盛り上がり(もりあがり)まして", "zh": "热烈起来了"}, {"start": 32.0, "end": 33.0, "reading": "もう最終(さいしゅう)の飛行機(ひこうき)", "zh": "已经是最后的飞机"}, {"start": 33.0, "end": 34.0, "reading": "時間(じかん)ギリギリまで", "zh": "直到时间勉强够的时候"}, {"start": 34.0, "end": 36.0, "reading": "ずっと滞在(たいざい)していました", "zh": "一直停留着"}, {"start": 36.0, "end": 37.0, "reading": "そして今(いま)", "zh": "然后现在"}, {"start": 37.0, "end": 39.0, "reading": "夜遅く(よるおそく)", "zh": "深夜"}, {"start": 39.0, "end": 40.0, "reading": "空港線(くうこうせん)の電車(でんしゃ)に乗って(のって)", "zh": "乘坐机场线的电车"}, {"start": 40.0, "end": 41.0, "reading": "もうまもなく", "zh": "马上就要"}, {"start": 41.0, "end": 43.0, "reading": "福岡空港(ふくおかくうこう)に戻っ(もどっ)ていくところです", "zh": "正在返回福冈机场的途中"}, {"start": 43.0, "end": 45.4, "reading": "ちなみに", "zh": "顺便一提"}, {"start": 45.4, "end": 46.4, "reading": "私(わたし)はこの間(かん)", "zh": "我在前些天"}, {"start": 46.4, "end": 47.4, "reading": "前日(ぜんじつ)空(そら)の", "zh": "前日空的"}, {"start": 48.4, "end": 49.4, "reading": "ダイヤモンド会員(かいいん)か", "zh": "是钻石会员还是"}, {"start": 49.4, "end": 51.4, "reading": "それを修行(しゅぎょう)するみたいなことを", "zh": "说了要修行那个之类的事"}, {"start": 51.4, "end": 52.4, "reading": "言い(いい)ましたけれど", "zh": "不过说过了"}, {"start": 52.4, "end": 54.4, "reading": "このダイヤモンド会員(かいいん)の修行(しゅぎょう)は", "zh": "这个钻石会员的修行"}, {"start": 54.4, "end": 56.4, "reading": "この福岡空港(ふくおかくうこう)に行く(いく)", "zh": "去这个福冈机场"}, {"start": 56.4, "end": 58.4, "reading": "その時に(ときに)完全(かんぜん)に終了(しゅうりょう)になりました", "zh": "在那个时候完全结束了"}, {"start": 58.4, "end": 59.4, "reading": "帰り(かえり)は余っ(あまっ)ていたマイルを使って(つかって)", "zh": "回程使用剩下的里程"}, {"start": 59.4, "end": 60.4, "reading": "特典(とくてん)航空(こうくう)間(かん)で", "zh": "用奖励机票"}, {"start": 60.4, "end": 62.4, "reading": "お金(きん)を払わ(はらわ)ずに戻っ(もどっ)てきました", "zh": "没有付钱就回来了"}, {"start": 63.4, "end": 64.4, "reading": "これは前日(ぜんじつ)空(そら)のラウンジですが", "zh": "这是前日空的贵宾室"}, {"start": 64.4, "end": 65.4, "reading": "夜(よる)の遅い(おそい)時間(じかん)になると", "zh": "但到了夜晚很晚的时间"}, {"start": 65.4, "end": 67.4, "reading": "もうほとんど人(にん)がいないんですね", "zh": "已经几乎没有人呢"}, {"start": 67.4, "end": 68.4, "reading": "そしてまた帰り(かえり)の飛行機(ひこうき)も", "zh": "然后回程的飞机也"}, {"start": 68.4, "end": 69.4, "reading": "続い(つづい)ていたので", "zh": "因为还在继续"}, {"start": 69.4, "end": 70.4, "reading": "座席(ざせき)の上に(うえに)", "zh": "在座位上"}, {"start": 70.4, "end": 71.4, "reading": "足(あし)を少し(すこし)折り曲げ(おりまげ)て", "zh": "把脚稍微弯曲起来"}, {"start": 71.4, "end": 73.4, "reading": "もちろん靴(くつ)は抜き(ぬき)ましたけれど", "zh": "当然鞋子是脱了的"}, {"start": 73.4, "end": 74.4, "reading": "横向(よこむき)きになって", "zh": "变成侧躺的姿势"}, {"start": 74.4, "end": 76.4, "reading": "それでゴロゴロすることにしました", "zh": "然后决定就这样滚来滚去"}, {"start": 76.4, "end": 77.4, "reading": "帰り(かえり)の飛行機(ひこうき)も寝た(ねた)かったんですが", "zh": "回程的飞机也想睡觉的，但是"}, {"start": 77.4, "end": 78.4, "reading": "結構(けっこう)揺れ(ゆれ)て", "zh": "相当地摇晃"}, {"start": 78.4, "end": 79.4, "reading": "結局(けっきょく)のところ", "zh": "结果的所在"}, {"start": 79.4, "end": 81.4, "reading": "あまりしっかり休む(やすむ)ことはできませんでしたが", "zh": "没能好好地休息，但是"}, {"start": 81.4, "end": 84.4, "reading": "今年(こんねん)の仕事(しごと)もこれで全部(ぜんぶ)終わり(おわり)です", "zh": "今年的工作到此也全部结束了"}, {"start": 84.4, "end": 85.4, "reading": "もう既に(すでに)", "zh": "已经"}, {"start": 85.4, "end": 87.4, "reading": "年(ねん)は変わ(かわ)ってしまっていますけれど", "zh": "年份虽然已经变了"}, {"start": 87.4, "end": 89.4, "reading": "また今年(こんねん)も頑張っ(がんばっ)ておりますので", "zh": "今年也会继续努力，所以"}, {"start": 89.4, "end": 90.4, "reading": "視聴者(しちょうしゃ)の皆さん(みなさん)", "zh": "观众的各位"}, {"start": 90.4, "end": 92.4, "reading": "改め(あらため)てよろしくお願い(ねがい)致し(いたし)ます", "zh": "重新拜托请多关照了"}, {"start": 92.4, "end": 93.4, "reading": "ちょっと遅い(おそい)とこになってしまって", "zh": "稍微变成了晚了的时候"}, {"start": 93.4, "end": 94.4, "reading": "すみませんでした", "zh": "对不起"}, {"start": 94.4, "end": 95.4, "reading": "ありがとうございました", "zh": "谢谢"}]};

